{
  "name": "Runtime decision",
  "version": "1.0",
  "agents": [],
  "orchestrator": {
    "name": "decision",
    "strategy": "Pipeline",
    "pipeline": {
      "steps": [
        {
          "name": "classify",
          "type": "decision",
          "decision": {
            "backend": "laya",
            "input": {
              "from": "query"
